package com.utec.tropelcare.service;
import com.utec.tropelcare.dto.GuardianDto; import com.utec.tropelcare.exception.NotFoundException; import com.utec.tropelcare.repository.GuardianRepository; import org.springframework.stereotype.Service; import java.util.List;
@Service public class GuardianService{private final GuardianRepository repo; public GuardianService(GuardianRepository r){repo=r;} public List<GuardianDto> all(){return repo.findAll().stream().map(this::dto).toList();} public GuardianDto get(Long id){return dto(repo.findById(id).orElseThrow(()->new NotFoundException("No existe un guardián con id "+id)));} private GuardianDto dto(com.utec.tropelcare.entity.Guardian g){return new GuardianDto(g.getId(),g.getDisplayName(),g.getEmail(),g.getNotificationEmail(),g.getCreatedAt());}}
